:root {
  --ink: #e9e2d2;
  --ink-dim: #a9a292;
  --ink-faint: #6b675d;
  --blood: #9e2a24;
  --blood-bright: #d04438;
  --sick: #a8b087;
  --amber: #d9a05b;
  --panel: rgba(8, 8, 7, 0.78);
  --line: rgba(233, 226, 210, 0.16);
  --serif: 'Cormorant', 'Times New Roman', serif;
  --mono: 'Plex Mono', 'Courier New', monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #030303;
  color: var(--ink);
  font-family: var(--mono);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
  background: #030303;
}

body.playing { cursor: none; }
body.playing.paused { cursor: default; }

