  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 42%, rgba(0,0,0,0.28) 70%, rgba(0,0,0,0.82) 100%);
  mix-blend-mode: multiply;
}

#fx-scan {
  position: fixed;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0.13;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255,255,255,0.045) 0px,
    rgba(255,255,255,0.045) 1px,
    transparent 1px,
    transparent 3px
  );
}

.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.65s ease, visibility 0.65s;
}
.screen.visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.hidden { display: none !important; }

/* ─────────────────────────── loading ─────────────────────────── */

#loading {
  z-index: 60;
  background:
    radial-gradient(ellipse at 50% 45%, #101010 0%, #050505 55%, #000 100%);
  flex-direction: column;
}
.load-inner {
  width: min(440px, 78vw);
  text-align: center;
}
.load-mark {
  font-family: var(--serif);
  font-size: 34px;
  color: var(--blood-bright);
  opacity: 0.8;
  animation: loadPulse 3.2s ease-in-out infinite;
}
@keyframes loadPulse {
  0%, 100% { opacity: 0.25; transform: rotate(0deg); }
  50% { opacity: 0.9; transform: rotate(180deg); }
}
.load-title {
  font-family: var(--serif);
  font-weight: 300;
  font-size: clamp(20px, 3.4vw, 32px);
  letter-spacing: 0.42em;
  margin: 22px 0 38px;
  color: var(--ink-dim);
  text-indent: 0.42em;
}
.load-track {
  width: 100%;
  height: 1px;
  background: rgba(255,255,255,0.12);
  overflow: hidden;
}
#load-bar {
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, rgba(158,42,36,0.2), var(--blood-bright));
  box-shadow: 0 0 14px rgba(208,68,56,0.5);
  transition: width 0.35s ease;
}
.load-status {
  margin-top: 18px;
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ink-faint);
  min-height: 14px;
}

/* ─────────────────────────── menu ─────────────────────────── */

#menu {
  z-index: 30;
  background:
    linear-gradient(90deg, rgba(3,3,3,0.92) 0%, rgba(3,3,3,0.55) 42%, rgba(3,3,3,0.12) 72%, rgba(3,3,3,0.55) 100%),
    linear-gradient(0deg, rgba(3,3,3,0.96) 0%, transparent 34%, transparent 74%, rgba(3,3,3,0.72) 100%);
}
.menu-grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.35;
  background-image:
    repeating-linear-gradient(0deg, rgba(255,255,255,0.018) 0 1px, transparent 1px 2px),
    radial-gradient(circle at 18% 30%, rgba(160,150,120,0.06), transparent 22%),
    radial-gradient(circle at 82% 68%, rgba(120,30,26,0.07), transparent 28%);
  animation: grainShift 8s steps(8) infinite;
}
@keyframes grainShift {
  0%, 100% { transform: translate(0, 0); }
  25% { transform: translate(-1px, 1px); }
  50% { transform: translate(1px, -1px); }
  75% { transform: translate(1px, 1px); }
}
.menu-top {
  position: absolute;
  top: 42px;
  left: 50px;
  right: 50px;
  display: flex;
  justify-content: space-between;
}
.eyebrow {
  font-size: 9px;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.menu-center {
  position: relative;
  width: min(760px, 88vw);
  margin-top: -2vh;
  padding-left: clamp(0px, 4vw, 70px);
  text-align: left;
}
.menu-kicker {
  font-size: 9px;
  letter-spacing: 0.3em;
  color: var(--ink-faint);
  margin: 0 0 22px;
}
.title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 300;
  line-height: 0.82;
  text-transform: uppercase;
  color: #ece5d5;
  text-shadow: 0 0 60px rgba(190,180,150,0.12), 0 4px 40px rgba(0,0,0,0.9);
}
.title-the {
  display: block;
  font-size: clamp(16px, 2vw, 24px);
  letter-spacing: 0.9em;
  margin-bottom: 16px;
  color: var(--ink-dim);
}
.title-main {
  display: block;
  font-size: clamp(56px, 9.6vw, 132px);
  letter-spacing: 0.06em;
}
.title-gap { display: inline-block; width: 0.18em; }
.title-main::after {
  content: '';
  display: block;
  width: 62px;
  height: 1px;
  margin-top: 24px;
  background: linear-gradient(90deg, var(--blood-bright), transparent);
}
.menu-tag {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(17px, 1.7vw, 23px);
  color: var(--ink-dim);
  margin: 22px 0 40px;
  letter-spacing: 0.02em;
}
.menu-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 38px;
}
.menu-options {
  display: flex;
  gap: 34px;
  flex-wrap: wrap;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  width: min(520px, 100%);
}
.opt {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--ink-faint);
}
.opt input[type=range] {
  -webkit-appearance: none;
  appearance: none;
  width: 86px;
  height: 1px;
  background: rgba(255,255,255,0.2);
  outline: none;
  cursor: pointer;
}
.opt input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ink-dim);
  box-shadow: 0 0 8px rgba(255,255,255,0.3);
}
.opt output {
  font-size: 8px;
  color: var(--ink-dim);
  width: 20px;
}
.menu-bottom {
  position: absolute;
  bottom: 34px;
  left: 50px;
  right: 50px;
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--ink-faint);
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.menu-sep { opacity: 0.4; }
.pulse-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--blood-bright);
  box-shadow: 0 0 10px var(--blood-bright);
  animation: pulseDot 2.4s ease-in-out infinite;
}
@keyframes pulseDot {
  0%, 100% { opacity: 0.35; }
  50% { opacity: 1; }
}

/* ─────────────────────────── buttons ─────────────────────────── */

.btn {
  appearance: none;
  border: 1px solid rgba(233,226,210,0.2);
  background: rgba(9,9,8,0.35);
  color: var(--ink-dim);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 400;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  padding: 15px 26px;
  cursor: pointer;
  position: relative;
  transition: color 0.3s, border-color 0.3s, background 0.3s, letter-spacing 0.3s;
  backdrop-filter: blur(3px);
}
.btn:hover, .btn:focus-visible {
  color: #fff8e8;
  border-color: rgba(233,226,210,0.55);
  background: rgba(28,26,22,0.55);
  letter-spacing: 0.29em;
  outline: none;
}
.btn-primary {
  border-color: rgba(208,68,56,0.5);
  color: #ead9c8;
  background: linear-gradient(90deg, rgba(110,26,22,0.32), rgba(24,12,10,0.3));
  box-shadow: inset 0 0 30px rgba(158,42,36,0.08);
}
.btn-primary:hover {
  border-color: var(--blood-bright);
  background: linear-gradient(90deg, rgba(158,42,36,0.42), rgba(30,14,12,0.4));
  box-shadow: 0 0 34px rgba(158,42,36,0.2), inset 0 0 30px rgba(158,42,36,0.14);
}
.btn-ico { color: var(--blood-bright); margin-right: 8px; }

/* ─────────────────────────── HUD ─────────────────────────── */

#hud {
  position: fixed;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  font-family: var(--mono);
}
.hud-top {
  position: absolute;
  top: 30px;
  left: 34px;
  right: 34px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.hud-objective {
  display: flex;
  flex-direction: column;
  gap: 7px;
  max-width: 52vw;
}
.hud-label {
  font-size: 8px;
  letter-spacing: 0.28em;
  color: var(--ink-faint);
  text-transform: uppercase;
}
.hud-objective #objective-text {
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--ink-dim);
  text-shadow: 0 1px 8px #000;
}
.hud-counter { text-align: right; display: flex; flex-direction: column; gap: 5px; }
#memory-count {
  font-family: var(--serif);
  font-size: 30px;
  font-weight: 300;
  line-height: 1;
  color: var(--ink);
  text-shadow: 0 1px 14px #000;
}
#memory-count i { font-size: 13px; font-style: normal; color: var(--ink-faint); letter-spacing: 0.1em; }

.location {
  position: absolute;
  top: 31px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 8px;
  letter-spacing: 0.5em;
  color: var(--ink-faint);
  opacity: 0;
  transition: opacity 1.2s ease;
  text-transform: uppercase;
  text-indent: 0.5em;
}
.location.show { opacity: 0.85; }

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translate(-50%, -50%);
  opacity: 0.6;
  transition: opacity 0.25s, transform 0.25s;
}
.crosshair span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(233,226,210,0.75);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 6px rgba(255,255,255,0.4);
  transition: width 0.25s, height 0.25s, background 0.25s;
}
.crosshair.active { opacity: 1; transform: translate(-50%,-50%) scale(1.1); }
.crosshair.active span { width: 8px; height: 8px; background: transparent; border: 1px solid rgba(233,226,210,0.9); }

.prompt {
  position: absolute;
  left: 50%;
  top: calc(50% + 44px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 9px;
  letter-spacing: 0.22em;
  color: var(--ink);
  background: rgba(5,5,4,0.55);
  border: 1px solid rgba(233,226,210,0.14);
  padding: 9px 14px;
  backdrop-filter: blur(4px);
  white-space: nowrap;
  animation: promptIn 0.3s ease;
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 6px); } }
kbd {
  display: inline-block;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--ink);
  border: 1px solid rgba(233,226,210,0.32);
  padding: 3px 6px;
  min-width: 19px;
  text-align: center;
  background: rgba(255,255,255,0.04);
}
.prompt kbd { border-color: rgba(208,68,56,0.6); color: #f0d3c6; }

.hud-bottom {
  position: absolute;
  left: 34px;
  right: 34px;
  bottom: 30px;
  display: flex;
  justify-content: space-between;
  gap: 40px;
}
.meter { width: min(230px, 32vw); }
.meter-right { text-align: right; }
.meter-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--ink-faint);
}
.meter-head em { font-style: normal; color: var(--sick); margin-left: 6px; letter-spacing: 0.1em; }
.meter-head em.off { color: var(--blood); }
.meter-head span:last-child { color: var(--ink-dim); font-size: 9px; }
.meter-track {
  height: 2px;
  background: rgba(255,255,255,0.11);
  overflow: hidden;
}
.meter-fill {
  height: 100%;
  width: 100%;
  transition: width 0.3s linear, background 0.5s;
}
.meter-fill.sanity { background: linear-gradient(90deg, #6f7a5a, #bcc79a); box-shadow: 0 0 10px rgba(168,176,135,0.4); }
.meter-fill.sanity.low { background: linear-gradient(90deg, #5b1714, #b5382f); box-shadow: 0 0 12px rgba(180,56,47,0.55); }
.meter-fill.battery { background: linear-gradient(90deg, #6d5731, #e0b070); box-shadow: 0 0 10px rgba(217,160,91,0.4); }
.meter-fill.battery.low { background: linear-gradient(90deg, #5b1714, #b5382f); }

.subtitle {
  position: absolute;
  left: 50%;
  bottom: 100px;
  transform: translateX(-50%);
  width: min(720px, 82vw);
  text-align: center;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(18px, 2vw, 25px);
  font-weight: 300;
  line-height: 1.4;
  color: #e5dcc8;
  text-shadow: 0 2px 18px #000, 0 0 40px #000;
  opacity: 0;
  transition: opacity 0.6s ease;
}
.subtitle.show { opacity: 1; }
.subtitle::before {
  content: '';
  display: block;
  width: 26px;
  height: 1px;
  background: rgba(208,68,56,0.6);
  margin: 0 auto 14px;
}

.flash-warning {
  position: absolute;
  left: 50%;
  top: 24%;
  transform: translateX(-50%);
  font-size: 9px;
  letter-spacing: 0.34em;
  color: var(--blood-bright);
  opacity: 0;
  text-shadow: 0 0 20px rgba(208,68,56,0.5);
  animation: warnBlink 1.4s steps(2) infinite;
}
.flash-warning.show { opacity: 0.9; }
@keyframes warnBlink { 0%, 100% { opacity: 0.25; } 50% { opacity: 0.95; } }

/* ─────────────────────────── note ─────────────────────────── */

.note-screen {
  z-index: 26;
  background: rgba(2,2,2,0.62);
  backdrop-filter: blur(3px) grayscale(0.4);
  cursor: default;
}
.note-paper {
  width: min(520px, 84vw);
  max-height: 78vh;
  overflow: auto;
  background:
    linear-gradient(160deg, rgba(255,255,255,0.05), transparent 40%),
    #cfc4a9;
  color: #29241d;
  padding: 46px 48px 30px;
  box-shadow: 0 30px 90px rgba(0,0,0,0.8), inset 0 0 80px rgba(80,60,30,0.22);
  transform: rotate(-0.4deg);
  position: relative;
  font-family: var(--serif);
}
.note-paper::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 80% 8%, rgba(90,60,20,0.22), transparent 24%),
    radial-gradient(circle at 12% 90%, rgba(70,50,20,0.18), transparent 30%),
    repeating-linear-gradient(0deg, transparent 0 27px, rgba(70,60,40,0.12) 27px 28px);
  mix-blend-mode: multiply;
}
.note-paper p {
  position: relative;
  font-size: clamp(17px, 1.9vw, 22px);
  line-height: 1.65;
  margin: 0 0 34px;
  white-space: pre-line;
}
.note-paper footer {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid rgba(60,50,35,0.25);
  padding-top: 15px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: rgba(50,42,30,0.7);
}
.note-close { opacity: 0.7; }

/* ─────────────────────────── modals ─────────────────────────── */

.modal-screen {
  z-index: 32;
  background: rgba(2,2,2,0.72);
  backdrop-filter: blur(6px) grayscale(0.25);
}
.modal {
  width: min(700px, 88vw);
  max-height: 86vh;
  overflow: auto;
  background: linear-gradient(160deg, rgba(20,19,17,0.95), rgba(7,7,6,0.97));
  border: 1px solid rgba(233,226,210,0.14);
  padding: 44px 48px;
  box-shadow: 0 30px 100px rgba(0,0,0,0.8);
}
.modal-small { width: min(460px, 88vw); text-align: center; }
.modal h2 {
  font-family: var(--serif);
  font-weight: 300;
  font-size: clamp(30px, 4vw, 46px);
  margin: 10px 0 30px;
  color: var(--ink);
  letter-spacing: 0.02em;
}
.help-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px 18px;
  padding: 22px 0 28px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.help-grid > div p {
  margin: 9px 0 0;
  font-size: 9px;
  letter-spacing: 0.06em;
  color: var(--ink-faint);
  line-height: 1.5;
}
.help-grid kbd { margin-right: 3px; }
.help-notes { margin: 26px 0 30px; }
.help-notes p {
  font-family: var(--serif);
  font-size: 17px;
  line-height: 1.5;
  color: var(--ink-dim);
  margin: 0 0 12px;
}
.help-notes b { color: var(--ink); font-weight: 400; }
.help-notes .help-warn {
  font-style: italic;
  color: var(--blood-bright);
  margin-top: 22px;
  opacity: 0.85;
}
.pause-actions { display: flex; flex-direction: column; gap: 10px; margin: 0 auto 22px; width: min(280px, 100%); }
.pause-hint { font-size: 8px; letter-spacing: 0.15em; color: var(--ink-faint); }

/* ─────────────────────────── endings ─────────────────────────── */

.end-screen {
  z-index: 40;
  background: radial-gradient(ellipse at 50% 42%, rgba(28,8,6,0.94), rgba(2,2,2,0.985) 62%, #000 100%);
  text-align: center;
}
.end-screen .end-inner { width: min(720px, 88vw); }
.eyebrow.red { color: var(--blood-bright); }
.end-screen h1 {
  font-family: var(--serif);
  font-weight: 300;
  font-size: clamp(42px, 7vw, 82px);
  letter-spacing: 0.12em;
  margin: 18px 0 22px;
  color: #e9dfcd;
  text-shadow: 0 0 50px rgba(158,42,36,0.3);
}
.end-line {
  font-family: var(--serif);
  font-style: italic;
  font-size: 20px;
  color: var(--ink-dim);
  margin-bottom: 46px;
}
.end-screen .btn { margin: 0 6px; }
.ending-screen {
  background: radial-gradient(ellipse at 50% 35%, rgba(54,58,50,0.5), rgba(7,8,7,0.98) 62%, #000 100%);
}
.ending-screen h1 { color: #eee7d6; }
.end-copy { margin: 8px auto 38px; }
.end-copy p {
  font-family: var(--serif);
  font-size: 19px;
  color: var(--ink-dim);
  margin: 0 0 10px;
  line-height: 1.5;
}
.end-credit {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.32em;
  color: var(--ink-faint);
  line-height: 2;
  margin: 0 0 34px;
}
.end-credit span { font-family: var(--serif); font-style: italic; font-size: 14px; letter-spacing: 0.08em; text-transform: none; }

/* ─────────────────────────── intro / fade ─────────────────────────── */

.intro-card {
  position: fixed;
  inset: 0;
  z-index: 18;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  text-align: center;
  background: #030303;
  transition: opacity 1.6s ease;
}
.intro-card p {
  font-family: var(--serif);
  font-size: clamp(20px, 2.4vw, 30px);
  font-weight: 300;
  color: var(--ink-dim);
  opacity: 0;
  margin: 0 0 18px;
  letter-spacing: 0.02em;
  transition: opacity 1.4s ease;
  padding: 0 8vw;
}
.intro-card p.show { opacity: 1; }
.intro-card p.intro-1 { font-style: italic; }
.intro-card.hidden { display: none !important; }

.fade {
  position: fixed;
  inset: 0;
  z-index: 55;
  background: #000;
  opacity: 0;
  pointer-events: none;
  transition: opacity 1.2s ease;
}
.fade.on { opacity: 1; }
.fade.flash { background: #fff; transition: opacity 0.08s; opacity: 0.85; }

/* ─────────────────────────── responsive ─────────────────────────── */

@media (max-width: 760px) {
  .menu-top { left: 24px; right: 24px; top: 26px; }
  .menu-center { padding-left: 0; width: 90vw; }
  .menu-bottom { left: 24px; right: 24px; bottom: 22px; font-size: 7px; gap: 8px; }
  .title-main { font-size: clamp(44px, 14vw, 90px); }
  .title-the { letter-spacing: 0.6em; }
  .hud-top { left: 20px; right: 20px; top: 20px; }
  .hud-objective #objective-text { font-size: 9px; }
  .hud-bottom { left: 20px; right: 20px; bottom: 20px; gap: 18px; }
  .meter { width: 42vw; }
  .subtitle { bottom: 88px; }
  .help-grid { grid-template-columns: repeat(2, 1fr); }
  .modal { padding: 32px 26px; }
  .note-paper { padding: 34px 28px 24px; }
}

import * as THREE from '../vendor/three.module.js';

/* ─────────────────────────────────────────────────────────────
   Procedural texture atelier. Everything in the apartment is
   painted at runtime so the build has no external art assets.
   ───────────────────────────────────────────────────────────── */

function mulberry32(a) {
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeCanvas(size = 512) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}

function finish(canvas, repeatX = 1, repeatY = 1) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeatX, repeatY);
  tex.anisotropy = 8;
  return tex;
}

function grain(ctx, w, h, amount, rand, tint = [0, 0, 0]) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rand() - 0.5) * amount;
    d[i] = Math.max(0, Math.min(255, d[i] + n + tint[0]));
    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n + tint[1]));
    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n + tint[2]));
  }
  ctx.putImageData(img, 0, 0);
}

function stains(ctx, w, h, rand, count = 5, alpha = 0.2, hue = '40,26,12') {
  for (let i = 0; i < count; i++) {
    const x = rand() * w;
    const y = rand() * h;
    const r = 20 + rand() * 110;
    const g = ctx.createRadialGradient(x, y, 2, x, y, r);
    g.addColorStop(0, `rgba(${hue},${alpha})`);
    g.addColorStop(0.55, `rgba(${hue},${alpha * 0.5})`);
    g.addColorStop(1, `rgba(${hue},0)`);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    // drips
    const drips = 1 + Math.floor(rand() * 3);
    for (let d = 0; d < drips; d++) {
      const dx = x + (rand() - 0.5) * r * 1.1;
      const len = 15 + rand() * 100;
      const lg = ctx.createLinearGradient(dx, y, dx, y + len);
      lg.addColorStop(0, `rgba(${hue},${alpha * 0.8})`);
      lg.addColorStop(1, `rgba(${hue},0)`);
      ctx.strokeStyle = lg;
      ctx.lineWidth = 1 + rand() * 2;
      ctx.beginPath();
      ctx.moveTo(dx, y);
      ctx.lineTo(dx + (rand() - 0.5) * 8, y + len);
      ctx.stroke();
    }
  }
}

function cracks(ctx, w, h, rand, count = 4, color = 'rgba(30,25,20,0.35)') {
  ctx.strokeStyle = color;
  for (let i = 0; i < count; i++) {
    let x = rand() * w;
    let y = rand() * h;
    ctx.lineWidth = 0.5 + rand();
    ctx.beginPath();
    ctx.moveTo(x, y);
    const segs = 4 + Math.floor(rand() * 7);
    for (let s = 0; s < segs; s++) {
      x += (rand() - 0.5) * 34;
      y += rand() * 26;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

function fibers(ctx, w, h, rand, count, palette) {
  for (let i = 0; i < count; i++) {
    const x = rand() * w;
    const y = rand() * h;
    const len = 2 + rand() * 9;
    const a = rand() * Math.PI;
    ctx.strokeStyle = palette[Math.floor(rand() * palette.length)];
    ctx.globalAlpha = 0.1 + rand() * 0.28;
    ctx.lineWidth = 0.5 + rand() * 0.7;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(a) * len, y + Math.sin(a) * len);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

/* ───────────────────────── wallpaper ───────────────────────── */

export function wallpaperTexture(seed = 1, variant = 'olive') {
  const s = 512;
  const c = makeCanvas(s);
  const ctx = c.getContext('2d');
  const rand = mulberry32(seed);
  const pal = variant === 'rose'
    ? { base: '#5b4a45', dark: '#453833', light: '#6b5951', motif: '#3b2e2b', stain: '38,20,12' }
    : { base: '#4c4b3c', dark: '#3c3b30', light: '#5b5a48', motif: '#33342a', stain: '35,25,10' };
  ctx.fillStyle = pal.base;
  ctx.fillRect(0, 0, s, s);

  // vertical tone bands
  for (let x = 0; x < s; x += 32) {
    ctx.fillStyle = x % 64 === 0 ? pal.dark : pal.light;
    ctx.globalAlpha = 0.18;
    ctx.fillRect(x, 0, 16, s);
  }
  ctx.globalAlpha = 1;

  // damask motif
  const step = 128;
  for (let gy = -step; gy < s + step; gy += step) {
    for (let gx = -step; gx < s + step; gx += step) {
      const ox = gx + ((Math.floor(gy / step) % 2) * step) / 2;
      ctx.save();
      ctx.translate(ox, gy);
      ctx.strokeStyle = pal.motif;
      ctx.fillStyle = pal.motif;
      ctx.globalAlpha = 0.32;
      ctx.lineWidth = 1.6;
      // central stem
      ctx.beginPath();
      ctx.moveTo(64, 10);
      ctx.bezierCurveTo(44, 38, 82, 58, 64, 92);
      ctx.bezierCurveTo(46, 112, 70, 118, 64, 122);
      ctx.stroke();
      // symmetric leaves
      for (const dir of [-1, 1]) {
        for (let i = 0; i < 3; i++) {
          const y = 28 + i * 28;
          ctx.beginPath();
          ctx.moveTo(64, y);
          ctx.bezierCurveTo(64 + dir * 12, y - 14, 64 + dir * 38, y - 6, 64 + dir * 40, y + 6);
          ctx.bezierCurveTo(64 + dir * 34, y + 18, 64 + dir * 14, y + 12, 64, y + 2);
          ctx.closePath();
          ctx.fill();
        }
      }
      // crown
      ctx.beginPath();
      ctx.arc(64, 14, 8, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }
  ctx.globalAlpha = 1;

  stains(ctx, s, s, rand, 7, 0.26, pal.stain);
  cracks(ctx, s, s, rand, 5, 'rgba(25,20,15,0.25)');

  // peeling patches
  for (let i = 0; i < 3; i++) {
    const x = rand() * s;
    const y = rand() * s;
    ctx.beginPath();
    ctx.moveTo(x, y);
    const n = 7;
    for (let j = 0; j < n; j++) {
      const a = (j / n) * Math.PI * 2;
      const r = 8 + rand() * 26;
      ctx.lineTo(x + Math.cos(a) * r, y + Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = 'rgba(90,82,66,0.5)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(20,18,14,0.35)';
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  grain(ctx, s, s, 20, rand);
  return finish(c, 2, 2);
}

/* ───────────────────────── floors ───────────────────────── */

export function woodFloorTexture(seed = 3) {
  const s = 512;
  const c = makeCanvas(s);
  const ctx = c.getContext('2d');
  const rand = mulberry32(seed);
  ctx.fillStyle = '#2c2016';
  ctx.fillRect(0, 0, s, s);

  const plankH = 52;
  for (let row = 0; row < s / plankH; row++) {
    const y = row * plankH;
    const offset = (row % 3) * 90 + rand() * 40;
    for (let x = -200; x < s + 200; x += 180) {
      const px = x + offset;
      const tone = 30 + rand() * 26;
      ctx.fillStyle = `rgb(${tone + 14},${tone + 2},${Math.max(8, tone - 10)})`;
      ctx.fillRect(px + 2, y + 2, 176, plankH - 4);
      // grain
      for (let g = 0; g < 7; g++) {
        ctx.strokeStyle = `rgba(15,9,5,${0.08 + rand() * 0.12})`;
        ctx.lineWidth = 0.5 + rand();
        ctx.beginPath();
        const gy = y + 6 + rand() * (plankH - 12);
        ctx.moveTo(px + 6, gy);
        ctx.bezierCurveTo(px + 60, gy + (rand() - 0.5) * 8, px + 120, gy + (rand() - 0.5) * 8, px + 170, gy + (rand() - 0.5) * 5);
        ctx.stroke();
      }
      // knots
      if (rand() > 0.72) {
        const kx = px + 20 + rand() * 140;
        const ky = y + 12 + rand() * (plankH - 24);
        ctx.fillStyle = 'rgba(20,12,6,0.5)';
        ctx.beginPath();
        ctx.ellipse(kx, ky, 2 + rand() * 3, 1 + rand() * 2, rand() * 3, 0, Math.PI * 2);
        ctx.fill();
      }
      // seam
      ctx.fillStyle = 'rgba(8,5,3,0.75)';
      ctx.fillRect(px, y, 2, plankH);
    }
    ctx.fillStyle = 'rgba(8,5,3,0.8)';
    ctx.fillRect(0, y, s, 2);
  }

  stains(ctx, s, s, rand, 6, 0.3, '18,10,4');
  grain(ctx, s, s, 16, rand);
  return finish(c, 4, 5);
}

export function carpetTexture(seed = 7) {
  const s = 512;
