    ctx.strokeStyle = `rgba(255,255,255,${0.015 + rand() * 0.03})`;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(s, y + (rand() - 0.5) * 2);
    ctx.stroke();
    ctx.strokeStyle = `rgba(0,0,0,${0.02 + rand() * 0.04})`;
    ctx.beginPath();
    ctx.moveTo(0, y + 1);
    ctx.lineTo(s, y + 1);
    ctx.stroke();
  }
  for (let x = 0; x < s; x += 3) {
    ctx.strokeStyle = `rgba(0,0,0,${0.02 + rand() * 0.03})`;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, s);
    ctx.stroke();
  }
  stains(ctx, s, s, rand, 3, 0.2, '18,12,6');
  return finish(c, 3, 3);
}

