    ctx.lineWidth = 0.8;
    ctx.beginPath();
    let x = 34;
    ctx.moveTo(x, y);
    while (x < s - 34) {
      const w = 4 + rand() * 12;
      ctx.quadraticCurveTo(x + w * 0.5, y - 2 - rand() * 3, x + w, y);
      x += w + 1 + rand() * 3;
    }
    ctx.stroke();
  }
  grain(ctx, s, s, 10, rand);
  return finish(c, 1, 1);
}

export function glowTexture() {
  const s = 128;
  const c = makeCanvas(s);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(255,240,205,0.9)');
  g.addColorStop(0.25, 'rgba(240,210,160,0.35)');
  g.addColorStop(0.6, 'rgba(200,160,110,0.08)');
  g.addColorStop(1, 'rgba(200,160,110,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  return finish(c, 1, 1);
}

export function stainDecalTexture(seed = 59) {
  const s = 256;
  const c = makeCanvas(s);
  const ctx = c.getContext('2d');
  const rand = mulberry32(seed);
  ctx.clearRect(0, 0, s, s);
  const cx = s / 2;
  const cy = s / 2;
  const g = ctx.createRadialGradient(cx, cy, 2, cx, cy, s * 0.42);
  g.addColorStop(0, 'rgba(20,12,7,0.7)');
  g.addColorStop(0.45, 'rgba(28,17,9,0.42)');
  g.addColorStop(1, 'rgba(30,18,10,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, s * 0.42, 0, Math.PI * 2);
  ctx.fill();
  for (let i = 0; i < 16; i++) {
    const a = rand() * Math.PI * 2;
    const r = 20 + rand() * 85;
    ctx.fillStyle = `rgba(22,13,7,${0.15 + rand() * 0.3})`;
    ctx.beginPath();
    ctx.ellipse(cx + Math.cos(a) * r, cy + Math.sin(a) * r, 3 + rand() * 14, 2 + rand() * 9, rand() * 3, 0, Math.PI * 2);
    ctx.fill();
  }
  return finish(c, 1, 1);
}

/* ─────────────────────────────────────────────────────────────
   All sound is synthesised in the browser. No audio files.
   ───────────────────────────────────────────────────────────── */

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.volume = 0.7;
    this.muted = false;
    this.noise = null;
    this.nextBeat = 0;
    this.nextMusic = 0;
    this.nextWhisper = 0;
    this.entityLevel = 0;
    this.sanity = 1;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = this.ctx = new AC();
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.volume;
    this.master.connect(ctx.destination);

    // gentle bus compression so stingers don't clip
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 22;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.28;
    comp.connect(this.master);
    this.bus = comp;

    this.noise = this.makeNoise(3);
    this.ready = true;
    this.buildAmbience();
  }

  makeNoise(seconds) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * seconds);
    const buffer = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const data = buffer.getChannelData(ch);
      let last = 0;
      for (let i = 0; i < len; i++) {
        const white = Math.random() * 2 - 1;
        last = 0.985 * last + 0.015 * white;
        data[i] = white * 0.55 + last * 1.4;
      }
    }
    return buffer;
  }

  noiseSource(loop = true) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = loop;
    return src;
  }

  buildAmbience() {
    const ctx = this.ctx;

    // ── low, breathing drone ──
    this.droneGain = ctx.createGain();
    this.droneGain.gain.value = 0.055;
    const droneFilter = ctx.createBiquadFilter();
    droneFilter.type = 'lowpass';
    droneFilter.frequency.value = 210;
    droneFilter.Q.value = 1.2;
    this.droneGain.connect(droneFilter);
    droneFilter.connect(this.bus);

    const d1 = ctx.createOscillator();
    d1.type = 'sine';
    d1.frequency.value = 43.65;
    const d2 = ctx.createOscillator();
    d2.type = 'sawtooth';
    d2.frequency.value = 43.65 * 1.006;
    const d3 = ctx.createOscillator();
    d3.type = 'sine';
    d3.frequency.value = 87.3 * 0.997;
    const g2 = ctx.createGain();
    g2.gain.value = 0.22;
    const g3 = ctx.createGain();
    g3.gain.value = 0.16;
    d1.connect(this.droneGain);
    d2.connect(g2); g2.connect(this.droneGain);
    d3.connect(g3); g3.connect(this.droneGain);
    d1.start(); d2.start(); d3.start();
    this.droneOscs = [d1, d2, d3];

    // slow amplitude LFO
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.045;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.024;
    lfo.connect(lfoGain);
    lfoGain.connect(this.droneGain.gain);
    lfo.start();

    // ── rain against the windows ──
    const rain = this.noiseSource();
    const rainFilter = ctx.createBiquadFilter();
    rainFilter.type = 'bandpass';
    rainFilter.frequency.value = 1500;
    rainFilter.Q.value = 0.45;
    this.rainGain = ctx.createGain();
    this.rainGain.gain.value = 0.026;
    rain.connect(rainFilter);
    rainFilter.connect(this.rainGain);
    this.rainGain.connect(this.bus);
    rain.start();

    // rain body
    const rain2 = this.noiseSource();
    const rf2 = ctx.createBiquadFilter();
    rf2.type = 'lowpass';
    rf2.frequency.value = 420;
    const rg2 = ctx.createGain();
    rg2.gain.value = 0.03;
    rain2.connect(rf2); rf2.connect(rg2); rg2.connect(this.bus);
    rain2.start();

    // ── room tone / air ──
    const air = this.noiseSource();
    const airF = ctx.createBiquadFilter();
    airF.type = 'lowpass';
    airF.frequency.value = 170;
    const airG = ctx.createGain();
    airG.gain.value = 0.03;
    air.connect(airF); airF.connect(airG); airG.connect(this.bus);
    air.start();

    // ── entity presence bed (silent until needed) ──
    const pres = this.noiseSource();
    const presF = ctx.createBiquadFilter();
    presF.type = 'highpass';
    presF.frequency.value = 900;
    const presG = ctx.createGain();
    presG.gain.value = 0.0;
    pres.connect(presF); presF.connect(presG); presG.connect(this.bus);
    pres.start();
    this.presenceGain = presG;

    const sub = ctx.createOscillator();
    sub.type = 'sine';
    sub.frequency.value = 31;
    const subG = ctx.createGain();
    subG.gain.value = 0.0;
    sub.connect(subG); subG.connect(this.bus);
    sub.start();
    this.subGain = subG;

    // ── whisper bed, tied to sanity ──
    const wh = this.noiseSource();
    const whF = ctx.createBiquadFilter();
    whF.type = 'bandpass';
    whF.frequency.value = 2100;
    whF.Q.value = 1.8;
    const whG = ctx.createGain();
    whG.gain.value = 0;
    const whPan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    wh.connect(whF);
    if (whPan) { whF.connect(whPan); whPan.connect(whG); } else whF.connect(whG);
    whG.connect(this.bus);
    wh.start();
    this.whisperGain = whG;
    this.whisperPan = whPan;

    const whLfo = ctx.createOscillator();
    whLfo.frequency.value = 0.19;
    const whLfoG = ctx.createGain();
    whLfoG.gain.value = 900;
    whLfo.connect(whLfoG); whLfoG.connect(whF.frequency);
    whLfo.start();

    this.nextBeat = ctx.currentTime + 2;
    this.nextMusic = ctx.currentTime + 10;
    this.nextWhisper = ctx.currentTime + 6;
  }

  setVolume(v) {
    this.volume = v;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : v, this.ctx.currentTime, 0.08);
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : this.volume, this.ctx.currentTime, 0.08);
  }

  setSanity(s) {
    this.sanity = s;
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const target = (1 - s) * 0.018;
    this.whisperGain.gain.setTargetAtTime(target, t, 1.5);
    if (this.whisperPan) {
      this.whisperPan.pan.setTargetAtTime(Math.sin(t * 0.13) * 0.7, t, 2);
    }
    if (this.droneGain) this.droneGain.gain.setTargetAtTime(0.055 + (1 - s) * 0.035, t, 2);
  }

  setEntity(active, distance) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const near = active ? Math.max(0, 1 - distance / 14) : 0;
    this.entityLevel = near;
    this.presenceGain.gain.setTargetAtTime(near * 0.035, t, 0.25);
    this.subGain.gain.setTargetAtTime(near * 0.07, t, 0.4);
  }

  footstep(run = false) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this.noiseSource(false);
    src.playbackRate.value = 0.7 + Math.random() * 0.5;
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = run ? 480 : 330;
    f.Q.value = 1.4;
    const g = ctx.createGain();
    const vol = run ? 0.09 : 0.06;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + (run ? 0.16 : 0.22));
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t); src.stop(t + 0.3);

    // heel scuff
    const s2 = this.noiseSource(false);
    s2.playbackRate.value = 1.4;
    const f2 = ctx.createBiquadFilter();
    f2.type = 'bandpass';
    f2.frequency.value = 1600;
    const g2 = ctx.createGain();
    g2.gain.setValueAtTime(0.0001, t + 0.02);
    g2.gain.exponentialRampToValueAtTime(0.018, t + 0.03);
    g2.gain.exponentialRampToValueAtTime(0.0001, t + 0.13);
    s2.connect(f2); f2.connect(g2); g2.connect(this.bus);
    s2.start(t + 0.02); s2.stop(t + 0.2);
  }

  tone(freq, dur, type = 'sine', vol = 0.06, when = 0, dest = null, detune = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.value = freq;
    o.detune.value = detune;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(dest || this.bus);
    o.start(t); o.stop(t + dur + 0.05);
  }

  pickup() {
    if (!this.ready) return;
    this.tone(523.25, 1.2, 'sine', 0.045, 0);
    this.tone(783.99, 1.6, 'sine', 0.03, 0.08);
    this.tone(1046.5, 1.9, 'sine', 0.016, 0.16);
    this.tone(261.63, 2.4, 'sine', 0.03, 0);
    // reversed-ish breath
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this.noiseSource(false);
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(700, t);
    f.frequency.exponentialRampToValueAtTime(3200, t + 0.5);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.03, t + 0.35);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9);
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t); src.stop(t + 1);
  }

  battery() {
    if (!this.ready) return;
    this.tone(392, 0.18, 'square', 0.025, 0);
    this.tone(587.33, 0.28, 'triangle', 0.03, 0.09);
  }

  click() {
    if (!this.ready) return;
    this.tone(1600, 0.05, 'square', 0.012, 0);
    this.tone(900, 0.07, 'sine', 0.01, 0.01);
  }

  stinger() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    // dissonant string cluster
    for (const [f, d] of [[146.8, 0], [155.6, 6], [220, -4], [233, 9]]) {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.value = f;
      o.detune.value = d;
      const fl = ctx.createBiquadFilter();
      fl.type = 'lowpass';
      fl.frequency.setValueAtTime(900, t);
      fl.frequency.exponentialRampToValueAtTime(180, t + 2.4);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.035, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 2.6);
      o.connect(fl); fl.connect(g); g.connect(this.bus);
      o.start(t); o.stop(t + 2.8);
    }
    // noise hit
    const src = this.noiseSource(false);
    const f = ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 500;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.16, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t); src.stop(t + 0.6);
  }

  jumpscare() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    this.stinger();
    const src = this.noiseSource(false);
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(3000, t);
    f.frequency.exponentialRampToValueAtTime(180, t + 1.1);
    f.Q.value = 0.7;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.22, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.3);
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t); src.stop(t + 1.4);
    const o = ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(1200, t);
    o.frequency.exponentialRampToValueAtTime(48, t + 0.9);
    const og = ctx.createGain();
    og.gain.setValueAtTime(0.09, t);
    og.gain.exponentialRampToValueAtTime(0.0001, t + 1.2);
    o.connect(og); og.connect(this.bus);
    o.start(t); o.stop(t + 1.3);
  }

  thunder() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this.noiseSource(false);
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.setValueAtTime(320, t);
    f.frequency.exponentialRampToValueAtTime(60, t + 3.5);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.28, t + 0.05);
    g.gain.exponentialRampToValueAtTime(0.13, t + 0.6);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 4.2);
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t); src.stop(t + 4.4);
    this.tone(38, 3.5, 'sine', 0.09, 0.1);
    this.tone(57, 2.2, 'sine', 0.04, 0.2);
  }

  heartbeat(volume = 0.06) {
    if (!this.ready) return;
    this.tone(48, 0.16, 'sine', volume, 0);
    this.tone(43, 0.2, 'sine', volume * 0.7, 0.17);
  }

  whisper() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this.noiseSource(false);
    src.playbackRate.value = 0.6 + Math.random() * 0.5;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 1200 + Math.random() * 1800;
    f.Q.value = 3.5;
    const g = ctx.createGain();
    const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (pan) pan.pan.value = Math.random() * 1.6 - 0.8;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.035, t + 0.18);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9 + Math.random() * 0.5);
    src.connect(f);
    if (pan) { f.connect(pan); pan.connect(g); } else f.connect(g);
    g.connect(this.bus);
    src.start(t); src.stop(t + 1.6);
  }

  musicBox() {
    if (!this.ready) return;
    const motif = [220, 261.63, 329.63, 392.0, 329.63, 261.63, 246.94, 220, 196.0, 246.94, 293.66, 349.23];
    const count = 3 + Math.floor(Math.random() * 4);
    let when = 0;
    for (let i = 0; i < count; i++) {
      const f = motif[Math.floor(Math.random() * motif.length)];
      this.tone(f, 2.8, 'triangle', 0.013, when, null, (Math.random() - 0.5) * 18);
      this.tone(f * 2, 1.6, 'sine', 0.004, when + 0.01);
      when += 0.45 + Math.random() * 0.7;
    }
  }

  doorOpen() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this.noiseSource(false);
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.setValueAtTime(180, t);
    f.frequency.exponentialRampToValueAtTime(700, t + 1.2);
    f.Q.value = 5;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.09, t + 0.15);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.5);
    src.connect(f); f.connect(g); g.connect(this.bus);
    src.start(t); src.stop(t + 1.7);
    this.tone(58, 1.2, 'sine', 0.05, 0.1);
  }

  update(dt) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const sanity = this.sanity;
    const ent = this.entityLevel;

    // heartbeat speeds up with proximity / low sanity
    if (t > this.nextBeat) {
      const urgency = Math.max(ent, 1 - sanity);
      if (urgency > 0.18) {
        this.heartbeat(0.02 + urgency * 0.07);
        this.nextBeat = t + Math.max(0.42, 1.15 - urgency * 0.62);
      } else {
        this.nextBeat = t + 1.2;
      }
    }

    // whispers
    if (t > this.nextWhisper) {
      if (sanity < 0.72 || Math.random() < 0.1) this.whisper();
      this.nextWhisper = t + 3 + Math.random() * 8;
    }

    // music box
    if (t > this.nextMusic) {
      if (sanity > 0.25) this.musicBox();
      this.nextMusic = t + 22 + Math.random() * 30;
    }
  }
}

import * as THREE from '../vendor/three.module.js';

const vertexShader = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position.xy, 0.0, 1.0);
  }
`;

const fragmentShader = /* glsl */ `
  precision highp float;
  varying vec2 vUv;
  uniform sampler2D tDiffuse;
  uniform vec2 uResolution;
  uniform float uTime;
  uniform float uSanity;
  uniform float uEntity;
  uniform float uFlash;
  uniform float uDamage;
  uniform float uFade;
  uniform float uGlitch;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }

  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
  }

  void main() {
    vec2 uv = vUv;
    vec2 c = uv - 0.5;
    float r2 = dot(c, c);

    // slow breathing warp when composure is low
    float dread = 1.0 - uSanity;
    uv.x += sin(uv.y * 9.0 + uTime * 1.7) * 0.0018 * dread;
    uv.y += sin(uv.x * 7.0 + uTime * 1.3) * 0.0012 * dread;

    // very subtle lens curvature
    uv = 0.5 + c * (1.0 + r2 * 0.045);

    // VHS-style tear bands when the figure is close
    float bandSeed = floor(uv.y * 46.0 + uTime * 4.0);
    float band = step(0.94, hash(vec2(bandSeed, floor(uTime * 7.0))));
    uv.x += (hash(vec2(bandSeed, 3.1)) - 0.5) * 0.012 * band * (0.25 + uGlitch);

    // chromatic aberration grows with dread and proximity
    vec2 ab = c * (0.0012 + dread * 0.0055 + uEntity * 0.009) * (0.35 + r2 * 2.2);
    vec3 col;
    col.r = texture2D(tDiffuse, uv + ab).r;
    col.g = texture2D(tDiffuse, uv).g;
    col.b = texture2D(tDiffuse, uv - ab).b;

    // cheap bright-pass bloom (four taps)
    vec3 bloom = vec3(0.0);
    vec2 px = 1.5 / uResolution;
    bloom += max(texture2D(tDiffuse, uv + vec2(px.x, 0.0)).rgb - 0.58, 0.0);
    bloom += max(texture2D(tDiffuse, uv - vec2(px.x, 0.0)).rgb - 0.58, 0.0);
    bloom += max(texture2D(tDiffuse, uv + vec2(0.0, px.y)).rgb - 0.58, 0.0);
    bloom += max(texture2D(tDiffuse, uv - vec2(0.0, px.y)).rgb - 0.58, 0.0);
    bloom += max(texture2D(tDiffuse, uv + vec2(px.x, px.y) * 2.5).rgb - 0.62, 0.0);
    bloom += max(texture2D(tDiffuse, uv - vec2(px.x, px.y) * 2.5).rgb - 0.62, 0.0);
    col += bloom * 0.17;

    // grade: sickly shadows, warm highlights, pulled saturation
    float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
    col = mix(vec3(lum), col, 0.78 - dread * 0.18);
    col *= vec3(0.95, 1.0, 1.035);
    col = pow(col, vec3(0.96, 1.0, 1.04));
    col += vec3(0.006, 0.009, 0.008) * (1.0 - smoothstep(0.0, 0.35, lum));

    // vignette
    float vig = 1.0 - smoothstep(0.28, 0.88, length(c * vec2(1.0, 0.92)) * 1.35);
    vig *= 0.92 + 0.08 * sin(uTime * 0.6);
    col *= mix(0.45, 1.0, vig);

    // film grain
    float grain = hash(uv * uResolution.xy + fract(uTime) * 971.0) - 0.5;
    col += grain * (0.045 + dread * 0.05);

    // faint scanline texture
    col *= 1.0 - 0.028 * (0.5 + 0.5 * sin(uv.y * uResolution.y * 3.14159));

    // entity static
    float st = hash(uv * uResolution.xy * 0.35 + uTime * 90.0);
    col += (st - 0.5) * uEntity * 0.14;
    col = mix(col, col * vec3(1.1, 0.92, 0.9), uEntity * 0.3);

    // damage pulse at edges
    float edge = smoothstep(0.18, 0.72, length(c));
    col = mix(col, vec3(0.34, 0.015, 0.01), uDamage * edge * 0.8);

    // lightning / jumpscare flash
    col = mix(col, vec3(0.93, 0.94, 0.92), uFlash);

    // final fade
    col *= 1.0 - uFade;

    gl_FragColor = vec4(col, 1.0);
    #include <colorspace_fragment>
  }
`;

export class PostProcessor {
  constructor(renderer, scene, camera) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.time = 0;

    const size = new THREE.Vector2();
    renderer.getSize(size);
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    this.width = Math.max(1, Math.floor(size.x * dpr));
    this.height = Math.max(1, Math.floor(size.y * dpr));

    this.target = new THREE.WebGLRenderTarget(this.width, this.height, {
      type: THREE.HalfFloatType,
      minFilter: THREE.LinearFilter,
      magFilter: THREE.LinearFilter,
      depthBuffer: true,
      stencilBuffer: false,
    });
    this.target.texture.colorSpace = THREE.NoColorSpace;

    this.material = new THREE.ShaderMaterial({
      uniforms: {
        tDiffuse: { value: this.target.texture },
        uResolution: { value: new THREE.Vector2(this.width, this.height) },
        uTime: { value: 0 },
        uSanity: { value: 1 },
        uEntity: { value: 0 },
        uFlash: { value: 0 },
        uDamage: { value: 0 },
        uFade: { value: 0 },
        uGlitch: { value: 0 },
      },
      vertexShader,
      fragmentShader,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    });

    this.quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.material);
    this.quad.frustumCulled = false;
    this.postScene = new THREE.Scene();
    this.postScene.add(this.quad);
    this.postCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  }

  setSize(width, height) {
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    this.width = Math.max(1, Math.floor(width * dpr));
    this.height = Math.max(1, Math.floor(height * dpr));
    this.target.setSize(this.width, this.height);
    this.material.uniforms.uResolution.value.set(this.width, this.height);
  }

  render(dt, params = {}) {
    this.time += dt;
    const u = this.material.uniforms;
    u.uTime.value = this.time;
    if (params.sanity !== undefined) u.uSanity.value = params.sanity;
    if (params.entity !== undefined) u.uEntity.value = params.entity;
    if (params.flash !== undefined) u.uFlash.value = params.flash;
    if (params.damage !== undefined) u.uDamage.value = params.damage;
    if (params.fade !== undefined) u.uFade.value = params.fade;
    if (params.glitch !== undefined) u.uGlitch.value = params.glitch;

    this.renderer.setRenderTarget(this.target);
    this.renderer.clear();
    this.renderer.render(this.scene, this.camera);
    this.renderer.setRenderTarget(null);
    this.renderer.render(this.postScene, this.postCamera);
  }
}

import * as THREE from '../vendor/three.module.js';
import {
  wallpaperTexture, woodFloorTexture, carpetTexture, tileTexture, ceilingTexture,
  doorTexture, fabricTexture, sheetTexture, woodFurnitureTexture, metalTexture,
  photoTexture, portraitTexture, tvStaticTexture, rainTexture, paperTexture,
  glowTexture, stainDecalTexture,
} from './textures.js';

export const H = 2.85;
const WT = 0.16;
const EYE = 1.64;

function rectCollider(colliders, x, z, hw, hd) {
  colliders.push({ minX: x - hw, maxX: x + hw, minZ: z - hd, maxZ: z + hd });
}

function box(parent, w, h, d, x, y, z, mat, cast = true, receive = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  mesh.position.set(x, y, z);
  mesh.castShadow = cast;
  mesh.receiveShadow = receive;
  parent.add(mesh);
  return mesh;
}

function plane(parent, w, h, x, y, z, mat, rx = 0, ry = 0, rz = 0, receive = true) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  mesh.position.set(x, y, z);
  mesh.rotation.set(rx, ry, rz);
  mesh.receiveShadow = receive;
  parent.add(mesh);
  return mesh;
}

function texClone(tex, rx, ry) {
  const t = tex.clone();
  t.needsUpdate = true;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function standard(tex, rx, ry, opts = {}) {
  const map = texClone(tex, rx, ry);
  const mat = new THREE.MeshStandardMaterial({
    map,
    roughness: opts.roughness ?? 0.86,
    metalness: opts.metalness ?? 0.02,
    color: opts.color ?? 0xffffff,
    bumpMap: opts.bump === false ? null : map,
    bumpScale: opts.bumpScale ?? 0.018,
    emissive: opts.emissive ?? 0x000000,
    emissiveIntensity: opts.emissiveIntensity ?? 0,
    side: opts.side ?? THREE.FrontSide,
  });
  return mat;
}

function basic(tex, rx, ry, opts = {}) {
  const map = texClone(tex, rx, ry);
  return new THREE.MeshBasicMaterial({
    map,
    color: opts.color ?? 0xffffff,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    depthWrite: opts.depthWrite ?? true,
    blending: opts.blending ?? THREE.NormalBlending,
  });
}

export function buildWorld(scene) {
  const colliders = [];
  const interactables = [];
  const shards = [];
  const batteries = [];
  const notes = [];
  const flickerLights = [];
  const lightSources = [];
  const rainPlanes = [];
  const tvScreens = [];
  const mirrorMaterials = [];
  const animated = [];

  scene.fog = new THREE.FogExp2(0x050607, 0.052);
  scene.background = new THREE.Color(0x030303);

  /* ── textures & materials ─────────────────────────────────── */
  const T = {
    wall: wallpaperTexture(101, 'olive'),
    wallRose: wallpaperTexture(202, 'rose'),
    floor: woodFloorTexture(303),
    carpet: carpetTexture(404),
    tile: tileTexture(505),
    ceiling: ceilingTexture(606),
    door: doorTexture(707),
    fabric: fabricTexture(808),
    sheet: sheetTexture(909),
    wood: woodFurnitureTexture(111),
    metal: metalTexture(222),
    photo: photoTexture(333),
    portrait: portraitTexture(444),
    tv: tvStaticTexture(555),
    rain: rainTexture(666),
    paper: paperTexture(777),
    glow: glowTexture(),
    stain: stainDecalTexture(888),
  };

  const M = {
    wallHall: standard(T.wall, 2.4, 1.4, { roughness: 0.95, bumpScale: 0.024 }),
    wallLiving: standard(T.wall, 2.4, 1.4, { roughness: 0.95, bumpScale: 0.024, color: 0xd6d0c0 }),
    wallBed: standard(T.wallRose, 2.4, 1.4, { roughness: 0.95, bumpScale: 0.024, color: 0xcfc4bb }),
    wallBath: standard(T.tile, 2.2, 1.4, { roughness: 0.6, bumpScale: 0.008, color: 0xc8c8bd }),
    wallStudy: standard(T.wall, 2.4, 1.4, { roughness: 0.95, bumpScale: 0.024, color: 0xbdb9a8 }),
    floorHall: standard(T.floor, 3.2, 7.2, { roughness: 0.72, bumpScale: 0.03 }),
    floorLiving: standard(T.carpet, 3.2, 3.2, { roughness: 1, bumpScale: 0.05, color: 0xb9a89a }),
    floorBed: standard(T.carpet, 3, 3, { roughness: 1, bumpScale: 0.05, color: 0xa89a8e }),
    floorBath: standard(T.tile, 2.2, 2.4, { roughness: 0.52, bumpScale: 0.006 }),
    floorStudy: standard(T.floor, 3, 2.4, { roughness: 0.74, bumpScale: 0.03, color: 0xb0a58f }),
    ceiling: standard(T.ceiling, 3, 3, { roughness: 1, bumpScale: 0.03, color: 0x9a9484 }),
    door: standard(T.door, 1, 1, { roughness: 0.7, bumpScale: 0.02 }),
    fabric: standard(T.fabric, 2, 2, { roughness: 1, bumpScale: 0.03, color: 0x8d9182 }),
    sheet: standard(T.sheet, 2, 2, { roughness: 1, bumpScale: 0.02, color: 0xb8b2a2 }),
    wood: standard(T.wood, 2, 2, { roughness: 0.7, bumpScale: 0.02, color: 0x9a7f63 }),
    woodDark: standard(T.wood, 2, 2, { roughness: 0.75, bumpScale: 0.02, color: 0x6c5743 }),
    metal: standard(T.metal, 2, 2, { roughness: 0.42, metalness: 0.7, color: 0x9aa0a0 }),
    brass: new THREE.MeshStandardMaterial({ color: 0x8a6a35, roughness: 0.34, metalness: 0.9 }),
    black: new THREE.MeshStandardMaterial({ color: 0x0b0c0c, roughness: 0.92 }),
    dark: new THREE.MeshStandardMaterial({ color: 0x1b1a17, roughness: 0.9 }),
    white: new THREE.MeshStandardMaterial({ color: 0xb9b3a2, roughness: 0.7 }),
    ceramic: new THREE.MeshStandardMaterial({ color: 0xb6b2a6, roughness: 0.3, metalness: 0.05 }),
    glass: new THREE.MeshStandardMaterial({ color: 0x1b2830, roughness: 0.12, metalness: 0.4, transparent: true, opacity: 0.75 }),
    tv: new THREE.MeshBasicMaterial({ map: T.tv, toneMapped: false }),
    paper: standard(T.paper, 1, 1, { roughness: 0.9, bumpScale: 0.004, emissive: 0x2a2418, emissiveIntensity: 0.25 }),
    water: new THREE.MeshStandardMaterial({ color: 0x0b1213, roughness: 0.08, metalness: 0.85 }),
  };

  /* ── helpers ──────────────────────────────────────────────── */
  function wall(x1, z1, x2, z2, mat, h = H, opts = {}) {
    const dx = x2 - x1;
    const dz = z2 - z1;
    const len = Math.hypot(dx, dz);
    const cx = (x1 + x2) / 2;
    const cz = (z1 + z2) / 2;
    const geo = new THREE.BoxGeometry(len, h, WT);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(cx, h / 2, cz);
    mesh.rotation.y = -Math.atan2(dz, dx);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    scene.add(mesh);
    const pad = WT / 2;
    colliders.push({
      minX: Math.min(x1, x2) - pad,
      maxX: Math.max(x1, x2) + pad,
      minZ: Math.min(z1, z2) - pad,
      maxZ: Math.max(z1, z2) + pad,
    });
    if (opts.baseboard) {
      const bx = new THREE.Mesh(new THREE.BoxGeometry(len, 0.13, 0.045), M.woodDark);
      bx.position.set(cx, 0.065, cz);
      bx.rotation.y = mesh.rotation.y;
      bx.translateZ(WT / 2 + 0.023);
      scene.add(bx);
    }
    return mesh;
  }

  function floor(x1, z1, x2, z2, mat) {
    const w = x2 - x1;
    const d = z2 - z1;
    const m = plane(scene, w, d, (x1 + x2) / 2, 0.005, (z1 + z2) / 2, mat, -Math.PI / 2, 0, 0);
    m.receiveShadow = true;
    return m;
  }

  function ceiling(x1, z1, x2, z2) {
    const w = x2 - x1;
    const d = z2 - z1;
    return plane(scene, w, d, (x1 + x2) / 2, H, (z1 + z2) / 2, M.ceiling, Math.PI / 2, 0, 0);
  }

  function doorFrame(x, z, width, alongZ = true, h = 2.22) {
    const t = 0.09;
    const d = 0.26;
    if (alongZ) {
      box(scene, d, h, t, x, h / 2, z - width / 2, M.woodDark, false);
      box(scene, d, h, t, x, h / 2, z + width / 2, M.woodDark, false);
      box(scene, d, t, width + t, x, h, z, M.woodDark, false);
    } else {
      box(scene, t, h, d, x - width / 2, h / 2, z, M.woodDark, false);
      box(scene, t, h, d, x + width / 2, h / 2, z, M.woodDark, false);
      box(scene, width + t, t, d, x, h, z, M.woodDark, false);
    }
  }

  function stainDecal(x, y, z, ry, scale = 1, opacity = 0.55) {
    const m = new THREE.MeshBasicMaterial({
      map: T.stain, transparent: true, opacity, depthWrite: false,
      color: 0x1a120a, side: THREE.DoubleSide,
    });
    const p = plane(scene, scale, scale, x, y, z, m, 0, ry, 0, false);
    p.renderOrder = 1;
    return p;
  }

  function addGlowSprite(parent, color, scale, opacity = 0.7) {
    const mat = new THREE.SpriteMaterial({
      map: T.glow, color, transparent: true, opacity,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const s = new THREE.Sprite(mat);
    s.scale.set(scale, scale, 1);
    parent.add(s);
    return s;
  }

  /* ── architecture ─────────────────────────────────────────── */

  // floors
  floor(-1.2, -10, 1.2, 10, M.floorHall);
  floor(-6, -6, -1.2, 0, M.floorLiving);
  floor(1.2, -2, 6, 4, M.floorBed);
  floor(-4.8, 2, -1.2, 6, M.floorBath);
  floor(1.2, 6, 5.4, 10, M.floorStudy);

  // ceilings
  ceiling(-1.2, -10, 1.2, 10);
  ceiling(-6, -6, -1.2, 0);
  ceiling(1.2, -2, 6, 4);
  ceiling(-4.8, 2, -1.2, 6);
  ceiling(1.2, 6, 5.4, 10);

  // hallway walls, with openings for the four rooms
  wall(-1.2, -10, -1.2, -4.2, M.wallHall, H, { baseboard: true });
  wall(-1.2, -2.8, -1.2, 3.4, M.wallHall, H, { baseboard: true });
  wall(-1.2, 4.8, -1.2, 10, M.wallHall, H, { baseboard: true });
  wall(1.2, -10, 1.2, 0.2, M.wallHall, H, { baseboard: true });
  wall(1.2, 1.6, 1.2, 7.4, M.wallHall, H, { baseboard: true });
  wall(1.2, 8.8, 1.2, 10, M.wallHall, H, { baseboard: true });

  // hallway end + front wall
  wall(-1.2, 10, 1.2, 10, M.wallHall, H, { baseboard: true });
  wall(-1.2, -10, -0.72, -10, M.wallHall, H, { baseboard: true });
  wall(0.72, -10, 1.2, -10, M.wallHall, H, { baseboard: true });

  // living room
  wall(-6, -6, -6, 0, M.wallLiving, H, { baseboard: true });
  wall(-6, -6, -1.2, -6, M.wallLiving, H, { baseboard: true });
  wall(-6, 0, -1.2, 0, M.wallLiving, H, { baseboard: true });

  // bedroom
  wall(1.2, -2, 6, -2, M.wallBed, H, { baseboard: true });
  wall(6, -2, 6, 4, M.wallBed, H, { baseboard: true });
  wall(1.2, 4, 6, 4, M.wallBed, H, { baseboard: true });

  // bathroom
  wall(-4.8, 2, -4.8, 6, M.wallBath, H, { baseboard: true });
  wall(-4.8, 2, -1.2, 2, M.wallBath, H, { baseboard: true });
  wall(-4.8, 6, -1.2, 6, M.wallBath, H, { baseboard: true });

  // study
  wall(1.2, 6, 5.4, 6, M.wallStudy, H, { baseboard: true });
  wall(5.4, 6, 5.4, 10, M.wallStudy, H, { baseboard: true });
  wall(1.2, 10, 5.4, 10, M.wallStudy, H, { baseboard: true });

  // door frames
  doorFrame(-1.2, -3.5, 1.4, true);
  doorFrame(1.2, 0.9, 1.4, true);
  doorFrame(-1.2, 4.1, 1.4, true);
  doorFrame(1.2, 8.1, 1.4, true);
  doorFrame(0, -10, 1.44, false);

  // bathroom tiled wainscot
  const wainMat = standard(T.tile, 3, 1.2, { roughness: 0.5, bumpScale: 0.006, color: 0xc3c4ba });
  plane(scene, 3.6, 1.35, -1.285, 0.675, 4, wainMat, 0, Math.PI / 2, 0);
  plane(scene, 3.6, 1.35, -4.785, 0.675, 4, wainMat, 0, -Math.PI / 2, 0);
  plane(scene, 3.6, 1.35, -3.0, 0.675, 2.015, wainMat, 0, 0, 0);
  plane(scene, 3.6, 1.35, -3.0, 0.675, 5.985, wainMat, 0, Math.PI, 0);

  // hallway runner
  const runnerMat = standard(T.carpet, 1.2, 8, { roughness: 1, color: 0x8a6b62 });
  plane(scene, 1.5, 14.5, 0, 0.012, 0, runnerMat, -Math.PI / 2, 0, 0);

  // wall stains
  stainDecal(-1.105, 1.9, -6.7, Math.PI / 2, 1.6, 0.5);
  stainDecal(1.105, 2.2, 5.4, -Math.PI / 2, 1.4, 0.45);
  stainDecal(-3.3, 2.3, -0.075, Math.PI, 1.7, 0.4);
  stainDecal(3.7, 2.1, 3.925, Math.PI, 1.5, 0.38);
  stainDecal(-3.9, 1.6, 5.92, Math.PI, 1.2, 0.4);

  /* ── front door ───────────────────────────────────────────── */
  const doorGroup = new THREE.Group();
  const doorMesh = box(doorGroup, 1.38, 2.18, 0.075, 0, 1.09, 0, M.door);
  doorMesh.castShadow = true;
  // chain
  box(doorGroup, 0.42, 0.035, 0.03, 0.28, 1.28, -0.06, M.brass, false);
  const knob = new THREE.Mesh(new THREE.SphereGeometry(0.045, 12, 8), M.brass);
  knob.position.set(0.52, 1.03, -0.08);
  doorGroup.add(knob);
  const knob2 = knob.clone();
  knob2.position.z = 0.08;
  doorGroup.add(knob2);
  // light bleeding under the door
  const doorGlow = new THREE.Mesh(
    new THREE.PlaneGeometry(1.3, 0.035),
    new THREE.MeshBasicMaterial({ color: 0xd6b98a, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending })
  );
  doorGlow.rotation.x = -Math.PI / 2;
  doorGlow.position.set(0, 0.02, -9.87);
  scene.add(doorGlow);
  doorGroup.position.set(0, 0, -9.94);
  scene.add(doorGroup);

  const doorLight = new THREE.PointLight(0xd9b077, 1.1, 3.5, 2);
  doorLight.position.set(0, 0.25, -9.5);
  scene.add(doorLight);
  lightSources.push({ pos: new THREE.Vector3(0, 1.0, -9.5), radius: 2.2, base: 1.1, light: doorLight });

  const doorInteract = new THREE.Object3D();
  doorInteract.position.set(0, 1.1, -9.75);
  doorInteract.userData = { type: 'door', label: 'TRY THE DOOR' };
  scene.add(doorInteract);
  interactables.push(doorInteract);

  /* ── lighting fixtures ────────────────────────────────────── */

  function ceilingBulb(x, z, color, intensity, distance, opts = {}) {
    const g = new THREE.Group();
    g.position.set(x, H, z);
    const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, opts.drop ?? 0.35, 6), M.black);
    wire.position.y = -(opts.drop ?? 0.35) / 2;
    g.add(wire);
    const shade = new THREE.Mesh(
      new THREE.ConeGeometry(0.19, 0.17, 16, 1, true),
      new THREE.MeshStandardMaterial({ color: 0x2a2721, roughness: 0.6, metalness: 0.3, side: THREE.DoubleSide })
    );
    shade.position.y = -(opts.drop ?? 0.35) - 0.02;
    g.add(shade);
    const bulb = new THREE.Mesh(
      new THREE.SphereGeometry(0.05, 12, 8),
      new THREE.MeshBasicMaterial({ color, toneMapped: false })
    );
    bulb.position.y = -(opts.drop ?? 0.35) - 0.1;
    g.add(bulb);
    scene.add(g);

    const light = new THREE.PointLight(color, intensity, distance, 2);
    light.position.set(x, H - (opts.drop ?? 0.35) - 0.12, z);
    scene.add(light);
    if (opts.shadow) {
      light.castShadow = true;
      light.shadow.mapSize.set(512, 512);
      light.shadow.bias = -0.002;
      light.shadow.camera.near = 0.1;
      light.shadow.camera.far = 10;
    }
    lightSources.push({ pos: light.position.clone(), radius: distance * 0.55, base: intensity, light, bulb, flicker: opts.flicker });
    if (opts.flicker) flickerLights.push({ light, bulb, base: intensity, phase: Math.random() * 10, style: opts.flicker, baseColor: new THREE.Color(color) });
    return light;
  }

  // hallway bulbs
  ceilingBulb(0, -6.2, 0xffd7a0, 4.6, 7, { drop: 0.32, flicker: 'soft' });
  ceilingBulb(0, -0.6, 0xffd7a0, 3.6, 6.5, { drop: 0.3, flicker: 'soft' });
  ceilingBulb(0, 5.4, 0xffcf95, 4.2, 7, { drop: 0.32, flicker: 'soft' });

  // living room floor lamp
  const lampG = new THREE.Group();
  lampG.position.set(-5.45, 0, -1.1);
  box(lampG, 0.36, 0.04, 0.36, 0, 0.02, 0, M.metal, false);
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 1.5, 8), M.metal);
  pole.position.y = 0.76;
  lampG.add(pole);
  const shadeMat = new THREE.MeshStandardMaterial({ color: 0x9a7d5c, roughness: 0.9, side: THREE.DoubleSide, emissive: 0x2b1d0e, emissiveIntensity: 0.4 });
  const shade = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.34, 0.34, 20, 1, true), shadeMat);
  shade.position.y = 1.52;
  lampG.add(shade);
