  }
  wallPhoto(-1.105, 1.7, -7.4, Math.PI / 2, T.photo);
  wallPhoto(-1.105, 1.72, -0.7, Math.PI / 2, T.photo);
  wallPhoto(1.105, 1.68, 5.9, -Math.PI / 2, T.photo);
