302: function entityLOS(from, to) {
303:   const dx = to.x - from.x;
304:   const dz = to.z - from.z;
305:   const dist = Math.hypot(dx, dz);
306:   const steps = Math.max(2, Math.ceil(dist / 0.22));
307:   for (let i = 1; i < steps - 1; i++) {
308:     const t = i / steps;
309:     const x = from.x + dx * t;
310:     const z = from.z + dz * t;
311:     for (const c of world.colliders) {
312:       if (c.wall && x > c.minX + 0.02 && x < c.maxX - 0.02 && z > c.minZ + 0.02 && z < c.maxZ - 0.02) {
313:         return true;
314:       }
315:     }
316:   }
317:   return false;
318: }
