320: function entityTarget() {
321:   if (Math.abs(player.pos.x) < 1.2) return player.pos;
322:   const door = ROOM_DOORS[state.room];
323:   if (!door) return player.pos;
324:   const dx = entity.group.position.x - door.x;
325:   const dz = entity.group.position.z - door.z;
326:   if (Math.hypot(dx, dz) < 1.25) return player.pos;
327:   return { x: door.x, z: door.z };
328: }
