330: function updateEntity(dt) {
331:   if (entity.cooldown > 0) entity.cooldown -= dt;
332:   if (!entity.active) {
333:     entity.distance = 999;
334:     entity.visible = false;
335:     return;
336:   }
337: 
338:   const ex = entity.group.position.x;
339:   const ez = entity.group.position.z;
340:   const dx = player.pos.x - ex;
341:   const dz = player.pos.z - ez;
342:   const dist = Math.hypot(dx, dz);
343:   entity.distance = dist;
344: 
345:   const camDir = camera.getWorldDirection(tmpV);
346:   const toEnt = tmpV2.set(ex, 1.35, ez).sub(camera.position);
347:   const flatDist = Math.max(0.001, Math.hypot(toEnt.x, toEnt.z));
348:   const dot = (toEnt.x * camDir.x + toEnt.z * camDir.z) / flatDist;
349:   const los = !entityLOS(camera.position, { x: ex, z: ez });
350: 
351:   entity.lit = state.flashlightOn && state.battery > 0 && dist < 15 && dot > 0.86 && los;
352:   entity.visible = dist < 18 && dot > 0.42 && los;
353: 
354:   // face the player
355:   entity.group.rotation.y = Math.atan2(dx, dz);
356:   entity.anim += dt;
357:   const sway = Math.sin(entity.anim * 2.1) * 0.055;
358:   entity.parts.torso.rotation.z = sway;
359:   entity.parts.head.rotation.z = -sway * 0.7;
360:   entity.parts.head.rotation.x = Math.sin(entity.anim * 0.7) * 0.06;
361:   entity.parts.armL.rotation.z = 0.12 + Math.sin(entity.anim * 1.4) * 0.05;
362:   entity.parts.armR.rotation.z = -0.12 - Math.sin(entity.anim * 1.4 + 1) * 0.05;
363:   entity.group.position.y = Math.sin(entity.anim * 1.7) * 0.012;
364: 
365:   if (entity.attack > 0) {
366:     entity.attack -= dt;
367:     entity.group.visible = true;
368:     if (entity.attack <= 0) {
369:       dissolveEntity(false);
370:     }
371:     return;
372:   }
373: 
374:   if (entity.lit) {
375:     entity.retreat += dt;
376:     state.sanity -= dt * 1.1;
377:     // forced back into the dark
378:     const len = Math.max(0.001, Math.hypot(dx, dz));
379:     entity.group.position.x -= (dx / len) * dt * 0.55;
380:     entity.group.position.z -= (dz / len) * dt * 0.55;
381:     const s = Math.max(0.72, 1 - entity.retreat * 0.12);
382:     entity.group.scale.set(s, s, s);
383:     if (entity.retreat > 1.9) dissolveEntity(true);
384:   } else if (entity.visible) {
385:     // It cannot move while watched. But being seen without the beam costs you.
386:     state.sanity -= dt * 5.2;
387:     entity.group.position.x += Math.sin(entity.anim * 3.1) * dt * 0.008;
388:   } else {
389:     const target = entityTarget();
390:     const tdx = target.x - entity.group.position.x;
391:     const tdz = target.z - entity.group.position.z;
392:     const tlen = Math.hypot(tdx, tdz);
393:     if (tlen > 0.02) {
394:       const speed = 0.62 + (1 - state.sanity / 100) * 0.55;
395:       entity.group.position.x += (tdx / tlen) * speed * dt;
396:       entity.group.position.z += (tdz / tlen) * speed * dt;
397:     }
398:   }
399: 
400:   entity.life += dt;
401:   if (dist < 1.35) beginAttack();
402:   else if (entity.life > 50) dissolveEntity(false);
403: }
