477: /* ── movement ───────────────────────────────────────────────── */
478: function blocked(x, z) {
479:   const r = player.radius;
480:   for (const c of world.colliders) {
481:     const nx = Math.max(c.minX, Math.min(x, c.maxX));
482:     const nz = Math.max(c.minZ, Math.min(z, c.maxZ));
483:     const dx = x - nx;
484:     const dz = z - nz;
485:     if (dx * dx + dz * dz < r * r) return true;
486:   }
487:   return false;
488: }
