490: function tryMove(dx, dz) {
491:   const dist = Math.hypot(dx, dz);
492:   const steps = Math.max(1, Math.ceil(dist / 0.07));
493:   const sx = dx / steps;
494:   const sz = dz / steps;
495:   for (let i = 0; i < steps; i++) {
496:     if (!blocked(player.pos.x + sx, player.pos.z)) player.pos.x += sx;
497:     if (!blocked(player.pos.x, player.pos.z + sz)) player.pos.z += sz;
498:   }
499: }
