501: function updatePlayer(dt) {
502:   const playing = state.mode === 'playing';
503:   let strafe = 0;
504:   let forwardInput = 0;
505:   if (playing) {
506:     if (keys.KeyW) forwardInput += 1;
507:     if (keys.KeyS) forwardInput -= 1;
508:     if (keys.KeyD) strafe += 1;
509:     if (keys.KeyA) strafe -= 1;
510:   }
511:   const run = playing && (keys.ShiftLeft || keys.ShiftRight);
512:   const speed = run ? 3.3 : 1.85;
513: 
514:   const sy = Math.sin(player.yaw);
515:   const cy = Math.cos(player.yaw);
516:   const fwdX = -sy;
517:   const fwdZ = -cy;
518:   const rightX = cy;
519:   const rightZ = -sy;
520: 
521:   let tx = (fwdX * forwardInput + rightX * strafe);
522:   let tz = (fwdZ * forwardInput + rightZ * strafe);
523:   const mag = Math.hypot(tx, tz);
524:   if (mag > 1) { tx /= mag; tz /= mag; }
525: 
526:   const accel = playing ? 10 : 4;
527:   player.vel.x += (tx * speed - player.vel.x) * Math.min(1, dt * accel);
528:   player.vel.z += (tz * speed - player.vel.z) * Math.min(1, dt * accel);
529:   if (!playing) {
530:     player.vel.x *= Math.max(0, 1 - dt * 6);
531:     player.vel.z *= Math.max(0, 1 - dt * 6);
532:   }
533: 
534:   if (Math.abs(player.vel.x) + Math.abs(player.vel.z) > 0.01) {
535:     tryMove(player.vel.x * dt, player.vel.z * dt);
536:   }
537: 
538:   const spd = Math.hypot(player.vel.x, player.vel.z);
539:   if (spd > 0.2) {
540:     player.walkPhase += dt * (run ? 10.5 : 7.2);
541:     player.stepDist += spd * dt;
542:     const stride = run ? 1.65 : 1.1;
543:     if (player.stepDist > stride) {
544:       player.stepDist = 0;
545:       if (playing) audio.footstep(run);
546:     }
547:   }
548: 
549:   const bobAmt = Math.min(1, spd / 3.2);
550:   player.bob = Math.sin(player.walkPhase * 2) * 0.026 * bobAmt;
551: 
552:   const lowSan = 1 - state.sanity / 100;
553:   const breath = Math.sin(state.time * 1.55) * 0.0045;
554:   const swayX = Math.sin(state.time * 0.43) * 0.012 * lowSan;
555:   const swayY = Math.sin(state.time * 0.57 + 1.2) * 0.008 * lowSan;
556: 
557:   state.shake = Math.max(0, state.shake - dt * 2.6);
558:   const sh = state.shake * state.shake;
559:   const shakeX = (Math.random() - 0.5) * 0.08 * sh;
560:   const shakeY = (Math.random() - 0.5) * 0.06 * sh;
561:   const shakeR = (Math.random() - 0.5) * 0.08 * sh;
562: 
563:   camera.position.set(
564:     player.pos.x + swayX + shakeX,
565:     world.EYE + player.bob + breath + swayY + shakeY,
566:     player.pos.z
567:   );
568:   camera.rotation.set(
569:     player.pitch + shakeR * 0.6,
570:     player.yaw + shakeR,
571:     -strafe * 0.012 + Math.sin(state.time * 0.6) * 0.012 * lowSan + shakeR * 0.4
572:   );
573: }
