575: function updateMenuCamera(dt, snap = false) {
576:   menuTime += dt;
577:   const t = menuTime;
578:   const z = 7.45 + Math.sin(t * 0.11) * 0.35;
579:   const x = Math.sin(t * 0.08) * 0.16;
580:   if (snap) {
581:     camera.position.set(x, 1.54, z);
582:     camera.rotation.set(-0.012, 0.035 + Math.sin(t * 0.09) * 0.02, 0);
583:   } else {
