585:     camera.position.y += (1.54 - camera.position.y) * Math.min(1, dt * 0.8);
586:     camera.position.z += (z - camera.position.z) * Math.min(1, dt * 0.8);
587:     camera.rotation.x += (-0.012 - camera.rotation.x) * Math.min(1, dt * 0.8);
588:     camera.rotation.y += (0.035 + Math.sin(t * 0.09) * 0.02 - camera.rotation.y) * Math.min(1, dt * 0.8);
589:     camera.rotation.z += (0 - camera.rotation.z) * Math.min(1, dt * 0.8);
