1129: 
1130:     // lightning
1131:     if (lightning > 0) {
1132:       lightning = Math.max(0, lightning - dt * 3.2);
1133:       const flick = lightning > 0.55 ? 1 : lightning > 0.3 ? 0.25 : 0.7;
1134:       lightningLight.intensity = lightning * 5 * flick;
1135:       for (const s of lightSources) if (s.window) s.light.intensity = s.base + lightning * 8 * flick;
1136:     } else {
1137:       lightningLight.intensity = 0;
1138:     }
