1148:       m.map.offset.y -= dt * 0.65;
1149:       m.map.offset.x += dt * 0.015;
1150:     }
1151: 
1152:     // shard / battery float
1153:     for (const s of shards) {
1154:       if (!s.userData.active) continue;
1155:       s.position.y = s.userData.baseY + Math.sin(time * 1.6 + s.userData.phase) * 0.035;
1156:       s.rotation.y = Math.sin(time * 0.7 + s.userData.phase) * 0.4;
