1170:       pos[i * 3 + 2] = d.z + Math.cos(time * 0.1 + d.p * 0.8) * 0.2;
1171:     }
1172:     dustGeo.attributes.position.needsUpdate = true;
1173:     dustMat.opacity = 0.22 + 0.1 * Math.sin(time * 0.4);
