import { chromium } from 'playwright';

const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__hollow && window.__hollow.world, null, { timeout: 60000 });
await page.waitForTimeout(1200);
console.log('loaded. mode=', await page.evaluate(() => window.__hollow.state.mode));

// start
await page.click('#btn-start');
await page.waitForFunction(() => window.__hollow.state.mode === 'playing', null, { timeout: 20000 });
await page.waitForTimeout(600);
console.log('playing. mode=', await page.evaluate(() => window.__hollow.state.mode));

// helper in page: find clear standing spot near a target and look at it
async function aimAtShard(i) {
  const info = await page.evaluate((idx) => {
    const H = window.__hollow;
    const s = H.world.shards[idx];
    const tx = s.position.x, ty = s.position.y, tz = s.position.z;
    const cols = H.world.colliders;
    function blocked(x, z) {
      const r = 0.29;
      for (const c of cols) {
        const nx = Math.max(c.minX, Math.min(x, c.maxX));
        const nz = Math.max(c.minZ, Math.min(z, c.maxZ));
        const dx = x - nx, dz = z - nz;
        if (dx * dx + dz * dz < r * r) return true;
      }
      return false;
    }
    let best = null;
    for (let ring = 1.1; ring <= 2.3; ring += 0.2) {
      for (let a = 0; a < Math.PI * 2; a += Math.PI / 16) {
        const x = tx + Math.cos(a) * ring;
        const z = tz + Math.sin(a) * ring;
        if (Math.abs(x) < 1.3 && Math.abs(z) < 9.3) continue; // keep out of hallway walls? not needed
        if (blocked(x, z)) continue;
        // line of sight through wall colliders only
        let los = true;
        const steps = Math.ceil(ring / 0.2);
        for (let k = 2; k < steps - 1; k++) {
          const t = k / steps;
          const px = x + (tx - x) * t, pz = z + (tz - z) * t;
          for (const c of cols) {
            if (c.wall && px > c.minX + 0.03 && px < c.maxX - 0.03 && pz > c.minZ + 0.03 && pz < c.maxZ - 0.03) { los = false; break; }
          }
          if (!los) break;
        }
        if (!los) continue;
        best = { x, z, ring };
        break;
      }
      if (best) break;
    }
    if (!best) return { ok: false };
    const eye = 1.55;
    const dx = tx - best.x, dz = tz - best.z, dy = ty - eye;
    const flat = Math.hypot(dx, dz);
    const yaw = Math.atan2(-dx, -dz);
    const pitch = Math.atan2(dy, flat);
    H.teleport(best.x, best.z, yaw, pitch);
    return { ok: true, from: best, target: { tx, ty, tz }, yaw, pitch };
  }, i);
  await page.waitForTimeout(260);
  return info;
}

for (let i = 0; i < 5; i++) {
  const aim = await aimAtShard(i);
  if (!aim.ok) { console.log('shard', i, 'NO SPOT'); continue; }
  const prompt = await page.evaluate(() => ({ text: document.getElementById('prompt-text').textContent, hidden: document.getElementById('prompt').classList.contains('hidden'), mode: window.__hollow.state.mode }));
  console.log('shard', i, 'from', aim.from, 'prompt=', JSON.stringify(prompt));
  await page.keyboard.press('KeyE');
  await page.waitForTimeout(500);
  const after = await page.evaluate(() => ({ memories: window.__hollow.state.memories, count: document.getElementById('memory-count').textContent, mode: window.__hollow.state.mode, objective: document.getElementById('objective-text').textContent }));
  console.log('  after E:', JSON.stringify(after));
  // dismiss entity/blackout not needed
}

// wait a moment then check door unlock and go to door
await page.waitForTimeout(1200);
const unlocked = await page.evaluate(() => ({ memories: window.__hollow.state.memories, doorUnlocked: window.__hollow.state.doorUnlocked, objective: document.getElementById('objective-text').textContent }));
console.log('unlock state:', JSON.stringify(unlocked));

// stand in front of door (door at x=-0.69, z=-9.94; hallway z ~ -8.6)
await page.evaluate(() => {
  const H = window.__hollow;
  H.teleport(-0.69, -8.75, Math.PI, -0.03);
});
await page.waitForTimeout(500);
const doorPrompt = await page.evaluate(() => ({ text: document.getElementById('prompt-text').textContent, hidden: document.getElementById('prompt').classList.contains('hidden'), mode: window.__hollow.state.mode }));
console.log('door prompt:', JSON.stringify(doorPrompt));
await page.screenshot({ path: 'screenshots/e2e-door.jpg', type: 'jpeg', quality: 78 });
await page.keyboard.press('KeyE');
await page.waitForTimeout(600);
console.log('after door E mode=', await page.evaluate(() => window.__hollow.state.mode));
await page.waitForTimeout(3800);
const ending = await page.evaluate(() => ({ mode: window.__hollow.state.mode, endingVisible: document.getElementById('ending').classList.contains('visible') }));
console.log('ending:', JSON.stringify(ending));
await page.screenshot({ path: 'screenshots/e2e-ending.jpg', type: 'jpeg', quality: 78 });

// return to title
await page.click('#btn-ending-title');
await page.waitForTimeout(800);
console.log('back to menu mode=', await page.evaluate(() => window.__hollow.state.mode));

// death test: start again, set sanity to 0 and wait
await page.click('#btn-start');
await page.waitForFunction(() => window.__hollow.state.mode === 'playing', null, { timeout: 20000 });
await page.evaluate(() => { window.__hollow.sanity(0.4); });
await page.waitForTimeout(700);
const death = await page.evaluate(() => ({ mode: window.__hollow.state.mode, deathVisible: document.getElementById('death').classList.contains('visible'), hudHidden: document.getElementById('hud').classList.contains('hidden') }));
console.log('death:', JSON.stringify(death));
await page.screenshot({ path: 'screenshots/e2e-death.jpg', type: 'jpeg', quality: 78 });

// retry
await page.click('#btn-retry');
await page.waitForTimeout(700);
console.log('retry mode=', await page.evaluate(() => window.__hollow.state.mode), 'sanity=', await page.evaluate(() => window.__hollow.state.sanity));

console.log('ERRORS:', errors.length ? JSON.stringify(errors, null, 2) : 'none');
await browser.close();

