await page.waitForTimeout(8500);
console.log('mode', await page.evaluate(() => window.__hollow.state.mode));
console.log(await page.evaluate(() => {
  const H = window.__hollow;
  const s = H.world.shards[0];
  H.teleport(-2.5, -3.15, Math.atan2(-(-3.6 + 2.5), -(-3.15 + 3.15)), Math.atan2(0.72 - 1.55, 1.1));
  return { pos: s.position.toArray(), active: s.userData.active, cam: H.player.pos.toArray(), yaw: H.player.yaw, pitch: H.player.pitch };
}));
await page.waitForTimeout(500);
console.log(await page.evaluate(() => {
  const H = window.__hollow;
  const s = H.world.shards[0];
  const THREEV = s.position.clone();
  s.getWorldPosition(THREEV);
  // project via camera
  const cam = H.world ? null : null;
  return { shardWorld: THREEV.toArray() };
}));
console.log('camera', await page.evaluate(() => {
  const H = window.__hollow;
  // find camera through scene
  let cam = null;
  H.world; // noop
  // camera is parent of flashlight
  cam = H.flashlight.parent;
  return { pos: cam.position.toArray(), rot: [cam.rotation.x, cam.rotation.y, cam.rotation.z], order: cam.rotation.order, matrixWorld: cam.matrixWorld.elements.slice(12, 15) };
}));
console.log('prompt', await page.evaluate(() => ({ hidden: document.getElementById('prompt').classList.contains('hidden'), text: document.getElementById('prompt-text').textContent, mode: window.__hollow.state.mode, active: window.__hollow.world.shards[0].userData.active })));
await page.screenshot({ path: 'screenshots/e2e-debug.jpg', type: 'jpeg', quality: 78 });
await browser.close();

