import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false, timeout: 60000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('response', (r) => { if (r.status() >= 400) errors.push('HTTP ' + r.status() + ' ' + r.url()); });

async function poll(fn, timeout = 20000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (await page.evaluate(fn)) return true;
    await page.waitForTimeout(200);
  }
  return false;
}
async function aim(type, index) {
  const info = await page.evaluate(({ type, index }) => {
    const H = window.__hollow;
    const list = type === 'note' ? H.world.notes : type === 'battery' ? H.world.batteries : H.world.shards;
    const s = list[index];
    const wp = s.position.clone();
    const tx = wp.x, ty = wp.y, tz = wp.z;
    const cols = H.world.colliders;
    function blocked(x, z) {
      const r = 0.29;
      for (const c of cols) {
        const nx = Math.max(c.minX, Math.min(x, c.maxX));
        const nz = Math.max(c.minZ, Math.min(z, c.maxZ));
        const dx = x - nx, dz = z - nz;
        if (dx * dx + dz * dz < r * r) return true;
      }
      return false;
    }
    let best = null;
    for (let ring = 1.05; ring <= 2.4 && !best; ring += 0.15) {
      for (let a = 0; a < Math.PI * 2; a += Math.PI / 24) {
        const x = tx + Math.cos(a) * ring;
        const z = tz + Math.sin(a) * ring;
        if (blocked(x, z)) continue;
        let los = true;
        const steps = Math.ceil(ring / 0.2);
        for (let k = 2; k < steps - 1 && los; k++) {
          const t = k / steps;
          const px = x + (tx - x) * t, pz = z + (tz - z) * t;
          for (const c of cols) {
            if (c.wall && px > c.minX + 0.03 && px < c.maxX - 0.03 && pz > c.minZ + 0.03 && pz < c.maxZ - 0.03) { los = false; break; }
          }
        }
        if (!los) continue;
        best = { x, z, ring };
        break;
      }
    }
    if (!best) return { ok: false };
    const eye = 1.55;
    const dx = tx - best.x, dz = tz - best.z, dy = ty - eye;
    const flat = Math.hypot(dx, dz);
    H.teleport(best.x, best.z, Math.atan2(-dx, -dz), Math.atan2(dy, flat));
    return { ok: true, from: best, target: [tx, ty, tz] };
  }, { type, index });
  if (!info.ok) { console.log('no aim spot for', type, index); return false; }
  await page.waitForTimeout(500);
  let seen = false;
  for (let k = 0; k < 25; k++) {
    const hidden = await page.evaluate(() => document.getElementById('prompt').classList.contains('hidden'));
    if (!hidden) { seen = true; break; }
    await page.waitForTimeout(150);
  }
  return seen;
}

